public struct UiTeam {
    public var id: String
    public var name: String
    public var abbrev: String
    /**
     * Primary brand color as 6-digit hex (no `#`), or `None` when unknown.
     */
    public var color: String?
    /**
     * Secondary brand color as 6-digit hex, or `None` when unknown.
     */
    public var altColor: String?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(id: String, name: String, abbrev: String,
                /**
                    * Primary brand color as 6-digit hex (no `#`), or `None` when unknown.
                    */ color: String?,
                /**
                    * Secondary brand color as 6-digit hex, or `None` when unknown.
                    */ altColor: String?)
    {
        self.id = id
        self.name = name
        self.abbrev = abbrev
        self.color = color
        self.altColor = altColor
    }
}

extension UiTeam: Equatable, Hashable {
    public static func == (lhs: UiTeam, rhs: UiTeam) -> Bool {
        if lhs.id != rhs.id {
            return false
        }
        if lhs.name != rhs.name {
            return false
        }
        if lhs.abbrev != rhs.abbrev {
            return false
        }
        if lhs.color != rhs.color {
            return false
        }
        if lhs.altColor != rhs.altColor {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(id)
        hasher.combine(name)
        hasher.combine(abbrev)
        hasher.combine(color)
        hasher.combine(altColor)
    }
}

